SELECT p.id AS product_id, p.name, p.grade, p.charge_name AS productChargeName, pi.project_status, p.brand_name, pi.id AS projectId, p.grade_id, p.charge_id AS productChargeId, pi.charge_id AS projectChargeId, p.type, p.approval_status, pi.charge_name AS projectChargeName, p.create_time, p.progress_status, p.image_url, p.property, p.category, pi.end_time, pph.name as projectPhase FROM product_info p LEFT JOIN project_info pi ON p.id = pi.product_id LEFT JOIN (select pt.product_id, COALESCE(min(pp.seq),max(ppe.seq)) as seq from project_task pt LEFT JOIN project_phase pp on pt.phase_id = pp.id and pt.product_id = pp.product_id and pt.status in (0,1,2,3,7,9,10) LEFT JOIN project_phase ppe on pt.phase_id = ppe.id and pt.product_id = ppe.product_id and pt.status = 4 GROUP BY pt.product_id) pp on p.id = pp.product_id LEFT JOIN project_phase pph on pp.product_id = pph.product_id and pp.seq = pph.seq WHERE P.delete_state = 0 AND p.is_finished_product_dev = 1
AND P.category_id = #{params.categoryId}
AND (P.name LIKE concat('%',#{params.searchKeyword},'%') OR p.id IN (SELECT pd.product_id FROM product_detail pd WHERE pd.sku_no LIKE concat('%',#{params.searchKeyword},'%')) OR p.spu_no LIKE concat('%',#{params.searchKeyword},'%'))
AND P.approval_status IN
#{state}
AND P.id IN
#{productId}
AND P.id NOT IN
#{productId}
AND p.grade_id IN
#{gradeId}
AND p.brand_id IN
#{brandId}
AND p.progress_status IN
#{progressStatus}
AND p.property_id IN
#{propertyId}
AND pph.name IN
#{phaseName}
AND p.charge_id IN
#{chargeId}
AND pi.charge_id IN
#{chargeId}
AND p.create_time >=#{params.startTime}
AND p.create_time <= #{params.startTime}
AND (p.id IN (SELECT pt.product_id FROM project_task pt WHERE 1 = 1 ${params.param}) or p.id IN (SELECT pt.product_id FROM project_task pt WHERE (pt.charge_id is null or pt.charge_id = '')) or p.id IN (SELECT pi.product_id FROM project_info pi WHERE (pi.charge_id is null or pi.charge_id = '')) )
ORDER BY p.create_time DESC

